package com.universalplatform.integration;
import com.fasterxml.jackson.databind.ObjectMapper; import com.universalplatform.identity.*; import com.universalplatform.security.*; import java.net.*; import java.net.http.*; import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ExternalNotificationService { private final TenantContext tenants; private final ActorContext actor; private final AuthorizationService auth; private final ExternalNotificationProviderRepository repo; private final IntegrationSecretCipher cipher; private final HttpClient http=HttpClient.newHttpClient(); private final ObjectMapper json=new ObjectMapper(); private final Clock clock=Clock.systemUTC(); ExternalNotificationService(TenantContext t,ActorContext a,AuthorizationService z,ExternalNotificationProviderRepository r,IntegrationSecretCipher c){tenants=t;actor=a;auth=z;repo=r;cipher=c;} @Transactional public ProviderView configure(String key,String type,String endpoint,String credential,long expectedVersion){auth.require(PermissionKey.EXTERNAL_NOTIFICATIONS_MANAGE);UUID t=tenants.requireTenantId();String k=req(key,64);String ty=req(type,24).toUpperCase(Locale.ROOT);if(!Set.of("HTTP_JSON","SLACK_WEBHOOK","TEAMS_WEBHOOK").contains(ty))throw new IllegalArgumentException("Unsupported notification provider");String e=url(endpoint);ExternalNotificationProvider p=repo.findByTenantIdAndProviderKey(t,k).orElse(null);Instant now=clock.instant();if(p!=null){if(p.version()!=expectedVersion)throw new IllegalArgumentException("Notification provider was modified by another request");p.update(ty,e,credential==null||credential.isBlank()?p.credentialCiphertext():cipher.encrypt(credential),now);}else{if(expectedVersion!=0)throw new IllegalArgumentException("Notification provider version is stale");p=repo.save(new ExternalNotificationProvider(UUID.randomUUID(),t,k,ty,e,credential==null?null:cipher.encrypt(credential),now));}return view(p);} @Transactional(readOnly=true) public List<ProviderView> list(){auth.require(PermissionKey.INTEROPERABILITY_VIEW);return repo.findAllByTenantIdAndEnabledTrue(tenants.requireTenantId()).stream().map(this::view).toList();} public void send(String key,String title,String body){auth.require(PermissionKey.EXTERNAL_NOTIFICATIONS_MANAGE);ExternalNotificationProvider p=repo.findByTenantIdAndProviderKey(tenants.requireTenantId(),key).filter(ExternalNotificationProvider::enabled).orElseThrow(()->new IllegalArgumentException("Notification provider not found"));try{Map<String,Object> payload=Map.of("title",title==null?"":title,"body",body==null?"":body);HttpRequest.Builder b=HttpRequest.newBuilder(URI.create(p.endpoint())).header("Content-Type","application/json");if(p.credentialCiphertext()!=null){String secret=cipher.decrypt(p.credentialCiphertext());if(p.providerType().equals("HTTP_JSON"))b.header("Authorization","Bearer "+secret);}HttpResponse<Void> r=http.send(b.POST(HttpRequest.BodyPublishers.ofString(json.writeValueAsString(payload))).build(),HttpResponse.BodyHandlers.discarding());if(r.statusCode()/100!=2)throw new IllegalStateException("External notification HTTP "+r.statusCode());}catch(Exception x){throw new IllegalStateException("External notification delivery failed",x);}} private ProviderView view(ExternalNotificationProvider p){return new ProviderView(p.id(),p.providerKey(),p.providerType(),p.endpoint(),p.version());} private static String req(String x,int m){if(x==null||x.isBlank()||x.trim().length()>m)throw new IllegalArgumentException("Invalid provider value");return x.trim();} private static String url(String x){try{URI u=URI.create(req(x,1000));if(!Set.of("https","http").contains(u.getScheme())||u.getHost()==null)throw new IllegalArgumentException();return u.toString();}catch(Exception e){throw new IllegalArgumentException("Invalid endpoint");}} public record ProviderView(UUID id,String providerKey,String providerType,String endpoint,long version){} }
